import {watermarkDocument,watermarkSettings,watermarkPlacement} from './watermark.js';
const presets={center:[50,50],top:[50,10],bottom:[50,90],topLeft:[10,10],topRight:[90,10],bottomLeft:[10,90],bottomRight:[90,90]};
export function watermarkEditor(){return `<fieldset class="watermark-editor"><legend>Automatic watermark</legend><label for="watermark-mode">Use as watermark</label><select id="watermark-mode" name="watermark_mode"><option value="text">Text</option><option value="image">Logo / image</option></select><div id="watermark-text-fields"><label for="watermark-text">Watermark text</label><input id="watermark-text" name="watermark_label" value="LexAmah" maxlength="60" pattern="[ -~]{1,60}" required></div><div id="watermark-image-fields" hidden><label for="watermark-image">Watermark logo (PNG or JPG, up to 2 MB)</label><input id="watermark-image" name="watermark_image" type="file" accept=".png,.jpg,.jpeg"><p class="muted">A transparent PNG works well. The logo is embedded into the document.</p></div><label for="watermark-preset">Placement</label><select id="watermark-preset"><option value="center">Centre</option><option value="top">Top centre</option><option value="bottom">Bottom centre</option><option value="topLeft">Top left</option><option value="topRight">Top right</option><option value="bottomLeft">Bottom left</option><option value="bottomRight">Bottom right</option><option value="custom">Custom position</option></select>${[['x','Horizontal position',50,0,100,'%'],['y','Vertical position',50,0,100,'%'],['size','Size (percentage of page width)',55,5,90,'%'],['opacity','Opacity',18,1,100,'%'],['rotation','Rotation',35,-90,90,'°']].map(([key,label,value,min,max,unit])=>`<label for="watermark-${key}">${label}: <output id="watermark-${key}-value">${value}${unit}</output></label><input id="watermark-${key}" name="watermark_${key}" type="range" min="${min}" max="${max}" value="${value}" data-watermark-unit="${unit}">`).join('')}<canvas id="watermark-layout" width="450" height="600" aria-label="Illustrative watermark placement preview"></canvas><p class="muted">Position is measured from the top left. The watermark is kept inside each visible page. This sample shows placement; use the document preview to check your file.</p><button type="button" class="btn" id="watermark-preview-button">Preview first page of selected file</button><p id="watermark-preview-status" role="status"></p><div id="watermark-document-preview"></div><p class="muted">Applied to every page of new or replacement uploads. Existing attachments change only when replaced.</p></fieldset>`;}
export function readWatermark(form){const raw=Object.fromEntries(new FormData(form));const settings=watermarkSettings({mode:raw.watermark_mode,text:raw.watermark_label,x:raw.watermark_x,y:raw.watermark_y,size:raw.watermark_size,opacity:raw.watermark_opacity,rotation:raw.watermark_rotation});return {...settings,image:raw.watermark_image};}
export function bindWatermarkEditor(form){
 const mode=form.querySelector('#watermark-mode');if(!mode)return;
 const status=form.querySelector('#watermark-preview-status'),preview=form.querySelector('#watermark-document-preview'),canvas=form.querySelector('#watermark-layout');let generation=0,logo=null,logoURL=null,task=null;
 const invalidate=()=>{generation++;if(task){task.destroy();task=null;}preview.replaceChildren();status.textContent='Update the document preview to see these settings on your file.';};
 const draw=()=>{try{const settings=readWatermark(form),ctx=canvas.getContext('2d');ctx.clearRect(0,0,450,600);ctx.fillStyle='#fff';ctx.fillRect(0,0,450,600);ctx.fillStyle='#ccd3cf';for(let row=0;row<15;row++)ctx.fillRect(35,40+row*34,row%3===0?300:375,4);ctx.font='bold 100px Arial';const ratio=settings.mode==='image'&&logo?logo.naturalWidth/logo.naturalHeight:ctx.measureText(settings.text).width/72;const p=watermarkPlacement({x:0,y:0,width:450,height:600},0,ratio,settings);ctx.save();ctx.globalAlpha=settings.opacity/100;ctx.translate(p.displayX,p.displayY);ctx.rotate(-settings.rotation*Math.PI/180);if(settings.mode==='image'&&logo)ctx.drawImage(logo,-p.width/2,-p.height/2,p.width,p.height);else{ctx.font=`bold ${p.width/(ctx.measureText(settings.text).width/100)}px Arial`;ctx.fillStyle='#405950';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(settings.mode==='image'?'LOGO':settings.text,0,0);}ctx.restore();}catch{}}
 const changed=()=>{invalidate();for(const input of form.querySelectorAll('[data-watermark-unit]'))form.querySelector(`#${input.id}-value`).textContent=input.value+input.dataset.watermarkUnit;draw();};
 mode.onchange=()=>{const image=mode.value==='image';form.querySelector('#watermark-text-fields').hidden=image;form.querySelector('#watermark-image-fields').hidden=!image;form.querySelector('#watermark-text').required=!image;form.querySelector('#watermark-text').disabled=image;form.querySelector('#watermark-image').disabled=!image;form.querySelector('#watermark-image').required=image;changed();};
 for(const input of form.querySelectorAll('[data-watermark-unit],#watermark-text'))input.oninput=()=>{if(['watermark-x','watermark-y'].includes(input.id))form.querySelector('#watermark-preset').value='custom';changed();};
 form.querySelector('#watermark-preset').onchange=event=>{const values=presets[event.target.value];if(values){form.querySelector('#watermark-x').value=values[0];form.querySelector('#watermark-y').value=values[1];changed();}};
 form.querySelector('#watermark-image').onchange=event=>{if(logoURL)URL.revokeObjectURL(logoURL);logo=null;const file=event.target.files[0];if(file){if(file.size>2*1024*1024){status.textContent='Choose a logo up to 2 MB.';return;}logoURL=URL.createObjectURL(file);const image=new Image();image.onload=()=>{if(form.querySelector('#watermark-image').files[0]!==file)return;logo=image;changed();};image.src=logoURL;}changed();};
 form.querySelector('#admin-upload').addEventListener('change',changed);
 form.querySelector('#watermark-preview-button').onclick=async event=>{const button=event.target;button.disabled=true;invalidate();const stamp=generation;try{const file=new FormData(form).get('upload');if(!file?.size)throw new Error('Select a new or replacement document first.');const result=await watermarkDocument(file,{...readWatermark(form),onProgress:message=>{if(stamp===generation)status.textContent=message;}});if(stamp!==generation)return;const pdfjs=await import('../vendor/pdfjs/build/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('../vendor/pdfjs/build/pdf.worker.mjs',import.meta.url).href;if(stamp!==generation)return;task=pdfjs.getDocument({data:new Uint8Array(await result.arrayBuffer()),isEvalSupported:false});const doc=await task.promise;const page=await doc.getPage(1);if(stamp!==generation)return;const viewport=page.getViewport({scale:Math.min(1.25,650/page.getViewport({scale:1}).width)}),pageCanvas=document.createElement('canvas');pageCanvas.width=Math.ceil(viewport.width);pageCanvas.height=Math.ceil(viewport.height);await page.render({canvasContext:pageCanvas.getContext('2d'),viewport}).promise;if(stamp!==generation)return;preview.replaceChildren(pageCanvas);status.textContent=`Actual first-page preview · ${doc.numPages} pages will receive this watermark. Nothing has been uploaded.`;}catch(err){if(stamp===generation)status.textContent=err.message;}finally{button.disabled=false;}};
 document.querySelector('#dialog').addEventListener('close',()=>{generation++;task?.destroy();if(logoURL)URL.revokeObjectURL(logoURL);},{once:true});draw();
}
